#nullable enable // autogenerated

using MVZ2.GameContent.Carts;
using MVZ2.Vanilla.Detections;
using MVZ2Logic.Entities;
using PVZEngine.Entities;
using UnityEngine;

namespace MVZ2.GameContent.Detections
{
    public class CartDetector : Detector
    {
        public CartDetector()
        {
        }
        protected override Bounds GetDetectionBounds(Entity self)
        {
            var size = new Vector3(64, 1000, 80);
            var center = self.Position + new Vector3(0, size.y * 0.5f, 0);
            return new Bounds(size, center);
        }
        public override bool ValidateTarget(DetectionParams self, Entity target)
        {
            var entity = self.entity;
            if (target.Position.x > entity.Position.x + CartCommonBehaviour.TRIGGER_DISTANCE)
                return false;
            if (target.GetLane() != entity.GetLane())
                return false;
            if (target.IsHarmless())
                return false;
            return base.ValidateTarget(self, target);
        }
    }
}
